		CheckpointID: cpID,
		SessionID:    sessionID,
		Strategy:     "manual-commit",
		Transcript:   []byte(`{"role":"assistant","content":"Hello"}`),
		Prompts:      []string{"Test prompt"},
		AuthorName:   "Test",
		AuthorEmail:  "test@test.com",
